#!/usr/bin/env python3
"""Seal completed bounded research, then write the exact asset manifest LAST."""
import pathlib,json,hashlib,gzip,datetime
from freeze import write,freeze
R=pathlib.Path(__file__).resolve().parents[1];S=R.parents[1];REPO=S.parents[2]
def sha(b):return hashlib.sha256(b).hexdigest()
def pin(p):
 b=p.read_bytes();assert len(b)<40000000;return {'path':str(p.relative_to(S)),'sha256':sha(b),'bytes':len(b)}
validation=json.loads((R/'validation.json').read_text());assert validation['status']=='PASS'
contract=json.loads((R/'priority-set.json').read_text());assert not contract['coordinator_acceptance'] and not contract['independent_peer_agreement'] and contract['peer_agent_id'] is None
important=[S/'turnout.md',S/'data/county-turnout.csv',R/'priority-set.json',R/'native-order-2024.csv',R/'priority-native-2024.csv',R/'remainder-native-2024.csv',R/'validation.json',R/'source/SCHEMA.md',R/'source/original-first-witness.json',R/'statewide-controls.json',R/'candidate-reconciliation.json']
seal={'schema_version':'AL-turnout-seal-v1','sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'completion':'Owned bounded original-first historical research/report/offline QA complete; worker turn ends after read-only manifest audit and coordinator handoff.','state':'AL','primary':{k:v for k,v in contract['coverage'].items() if k not in ['priority_keys','full_order','remainder_keys']},'native_coverage_by_year':{year:r['native_units'] for year,r in validation['measurements'].items()},'county_parents_per_year':67,'direct_original_checks':{'members':201,'raw_cells':6246656,'candidate_method_admin_cells':85129,'offline_check_groups':len(validation['checks'])},'pins':[pin(p) for p in important],'peer_agent_id':None,'independent_peer_agreement':False,'coordinator_acceptance':False,'published_by_worker':False,'git_commands_or_mutations_performed':False,'delegation_performed':False,'pending_peer_protocol':'Coordinator may arrange bounded SAME-ID reciprocal once a real independent peer is stable. Peer must independently extract originals before read-only comparison of all shared county/native/candidate/method fields, complete order and exact minimum80 priority. Never edit peer output to match. No peer existed at launch; no one was polled or restarted.','material_source_qualifications':['2024 Cleburne native ballot sum is 180 below separate official ballot report;2022 Cullman native ballot sum is 90 above report; candidate controls reconcile independently','native registration fields contain printed zero county rows and some blank cells, do not reproduce report registration totals; full-state native registration priority unestablished','Walker2024 presidential under/over fields missing47 units;2022 Senate under/over missing Butler23,Dale20,Tuscaloosa56;2020 Randolph blank-ballot field missing28 units','generic published Write-In counts are distinct from legal named/valid eligible write-in allocation; three PDF null/dash cells remain null despite independent native numeric zeros','historical native header identities do not establish current2026IDs/approved boundaries/crosswalk; current signed/sample ballot context is bounded, later amendments/legal eligibility not exhausted','no live collector, measured publication cadence, exact outstanding counts or calibrated2026 probability forecast'], 'manifest_rule':'asset-manifest.json is written last and excludes only itself; validation and seal contain no manifest digest; a read-only exact-membership/hash/size/link/cache audit follows.'}
write(R/'final-seal.json',json.dumps(seal,indent=2)+'\n')
# If resealing a later authorized version, preserve the prior manifest before enumerating all assets.
freeze(R/'asset-manifest.json')
paths=sorted([S/'turnout.md',S/'data/county-turnout.csv']+[p for p in R.rglob('*') if p.is_file() and p!=R/'asset-manifest.json'])
assert len(paths)==len(set(paths));assert not [p for p in paths if p.suffix=='.pyc' or any(x in p.parts for x in ['__pycache__','node_modules','.cache','.venv'])]
assets=[pin(p) for p in paths];external=[]
for r in json.loads((R/'source/original-receipts.json').read_text()):
 p=REPO/r['shared_path'];b=p.read_bytes();raw=gzip.decompress(b);assert sha(b)==r['stored_sha256'] and sha(raw)==r['raw_sha256'];assert len(b)<40000000
 external.append({'path':r['shared_path'],'stored_sha256':sha(b),'stored_bytes':len(b),'original_sha256':sha(raw),'original_bytes':len(raw),'receipt_reference':'data/turnout/source/original-receipts.json','reuse':'read-only; complete original body stored once in shared news gzip'})
manifest={'schema_version':'AL-turnout-assets-v1','scope':'Only turnout.md, data/county-turnout.csv and data/turnout/**. Excludes ONLY this manifest itself. Includes every authored script, history body/metadata, receipt, proof, current validation, seal and report.','assets':assets,'asset_count':len(assets),'total_owned_bytes':sum(x['bytes'] for x in assets),'largest_owned_bytes':max(x['bytes'] for x in assets),'external_originals':external,'all_stored_files_strictly_under_bytes':40000000,'no_dependency_or_cache_directories':True}
# Deliberately the final filesystem mutation in this run.
(R/'asset-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'seal_sha256':sha((R/'final-seal.json').read_bytes()),'manifest_sha256':sha((R/'asset-manifest.json').read_bytes()),'asset_count':len(assets),'total_owned_bytes':manifest['total_owned_bytes'],'largest_owned_bytes':manifest['largest_owned_bytes'],'pins':seal['pins']},indent=2))
